let tts = null;
let loading = null;
let queue = Promise.resolve();
let lastPercent = -1;
let lastAlive = 0;
const canceled = new Set();
const files = new Map();
const describe = (error) => String((error && error.message) || error || 'Unknown error').slice(0, 300);
